/*
 * Kitset — Shopify support drafter.
 *
 * Everything down to the adapter at the bottom is copied straight from
 * the project's classify.js and shopify.js and is covered by its tests.
 * Editing it here means the tests no longer describe what runs.
 */

/*
 * Reading a support email.
 *
 * Three jobs: throw away mail no human wrote, throw away the quoted history
 * underneath the reply, and work out which of the three questions is being
 * asked. When it is not clearly one of them, say so and let a person read it.
 * Guessing is what produces the wrong reply to a customer.
 */

/** Markers that begin the quoted history under a reply. */
const QUOTE_MARKERS = [
  /^\s*>/,
  /^\s*On .{5,120}\bwrote:\s*$/i,
  /^\s*-{2,}\s*Original Message\s*-{2,}\s*$/i,
  /^\s*_{10,}\s*$/,
  /^\s*From:\s*.+$/i,
  /^\s*Sent from my /i,
  /^\s*Begin forwarded message:\s*$/i,
];

/**
 * Keeps only what the person wrote this time.
 *
 * Without this, an old thread about a return keeps voting on every new
 * message in the same conversation.
 */
function stripQuotedHistory(body) {
  const lines = String(body || "").split(/\r?\n/);
  const kept = [];
  for (const line of lines) {
    if (QUOTE_MARKERS.some((marker) => marker.test(line))) break;
    kept.push(line);
  }
  // A reply that is nothing but quoted text leaves us with nothing. In that
  // case keep the original, so a human still sees something.
  const text = kept.join("\n").trim();
  return text.length > 0 ? text : String(body || "").trim();
}

const AUTOMATED_SENDERS = [
  "noreply",
  "no-reply",
  "no_reply",
  "donotreply",
  "do-not-reply",
  "mailer-daemon",
  "postmaster",
  "bounce",
  "notifications@shopify.com",
  "mailchimp",
  "newsletter",
];

const AUTOMATED_SUBJECTS = [
  /out of office/i,
  /automatic reply/i,
  /auto[- ]?reply/i,
  /delivery status notification/i,
  /undeliverable/i,
  /returned mail/i,
  /mail delivery (failed|subsystem)/i,
  /your order .* (is on the way|has shipped|confirmation)/i,
];

/**
 * True for machine mail: bounces, newsletters, out-of-office, Shopify's own
 * order confirmations. Answering any of these is at best noise and at worst
 * a loop of two robots emailing each other.
 */
function isAutomated(email) {
  const headers = {};
  for (const [rawKey, rawValue] of Object.entries(email.headers || {})) {
    const key = String(rawKey).toLowerCase();
    // Some mail parsers hand back the whole header line, name included, so
    // "Auto-Submitted: no" arrives where "no" was expected. Left alone, that
    // would mark ordinary human mail as automatic and answer nobody.
    const value = String(rawValue)
      .replace(new RegExp(`^\\s*${key.replace(/[^a-z0-9-]/g, "")}\\s*:\\s*`, "i"), "")
      .trim();
    headers[key] = value;
  }

  if (headers["auto-submitted"] && headers["auto-submitted"] !== "no") return true;
  if (headers["x-autoreply"]) return true;
  if (headers["x-autorespond"]) return true;
  if (headers["list-unsubscribe"]) return true;
  const precedence = (headers["precedence"] || "").toLowerCase();
  if (["bulk", "junk", "list", "auto_reply"].includes(precedence)) return true;

  const from = String(email.from || "").toLowerCase();
  if (AUTOMATED_SENDERS.some((needle) => from.includes(needle))) return true;

  const subject = String(email.subject || "");
  if (AUTOMATED_SUBJECTS.some((pattern) => pattern.test(subject))) return true;

  return false;
}

/*
 * Category scoring. Phrases are worth 3 because "delivery address" tells you
 * far more than "delivery" and "address" separately. Single words are worth 1.
 */
const SIGNALS = {
  order_status: {
    phrases: [
      "where is my order",
      "where's my order",
      "wheres my order",
      "where is my parcel",
      "where is my package",
      "track my order",
      "tracking number",
      "tracking info",
      "order status",
      "status of my order",
      "when will it arrive",
      "when will my order",
      "has it shipped",
      "has my order shipped",
      "not arrived",
      "hasn't arrived",
      "hasnt arrived",
      "still waiting",
      "no sign of",
      "any update on my order",
    ],
    words: [
      "tracking",
      "track",
      "shipped",
      "shipping",
      "dispatch",
      "dispatched",
      "delivery",
      "delivered",
      "arrive",
      "arrival",
      "eta",
      "late",
      "delayed",
      "waiting",
    ],
  },
  return_request: {
    phrases: [
      "want to return",
      "like to return",
      "can i return",
      "send it back",
      "send them back",
      "return this",
      "return it",
      "return label",
      "return policy",
      "refund me",
      "money back",
      "doesn't fit",
      "does not fit",
      "wrong item",
      "wrong size",
      "arrived damaged",
      "arrived broken",
      "start a return",
    ],
    words: [
      "return",
      "returning",
      "refund",
      "refunded",
      "exchange",
      "rma",
      "faulty",
      "damaged",
      "broken",
      "defective",
    ],
  },
  address_change: {
    phrases: [
      "change my address",
      "change the address",
      "wrong address",
      "update my address",
      "update the address",
      "new address",
      "different address",
      "delivery address",
      "shipping address",
      "i have moved",
      "i've moved",
      "ive moved",
      "deliver to a different",
      "send it to a different",
    ],
    words: ["address", "moved", "relocate", "relocated"],
  },
};

function scoreCategory(text, signals) {
  let score = 0;
  const hits = [];
  for (const phrase of signals.phrases) {
    if (text.includes(phrase)) {
      score += 3;
      hits.push(phrase);
    }
  }
  const words = text.split(/[^a-z0-9']+/).filter(Boolean);
  const wordSet = new Set(words);
  for (const word of signals.words) {
    if (wordSet.has(word)) {
      score += 1;
      hits.push(word);
    }
  }
  return { score, hits };
}

/**
 * Which of the three questions is this?
 *
 * Returns one of: order_status, return_request, address_change, unclear.
 * "unclear" covers both "no idea" and "two of them at once", because both
 * need the same thing: a person.
 */
function categorise(text) {
  const lower = String(text || "").toLowerCase();
  const scores = {};
  const hits = {};
  for (const [name, signals] of Object.entries(SIGNALS)) {
    const result = scoreCategory(lower, signals);
    scores[name] = result.score;
    hits[name] = result.hits;
  }

  const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const [bestName, bestScore] = ranked[0];
  const secondScore = ranked[1][1];

  if (bestScore === 0) {
    return { category: "unclear", reason: "no_signal", scores, hits: [] };
  }
  // Two categories both asked about means the customer asked two things. A
  // reply that answers one of them and ignores the other reads worse than no
  // reply at all.
  //
  // The runner-up has to clear two bars: an absolute one, so that a single
  // stray word like "delivery" in an address question is not treated as a
  // second question; and a relative one, so a passing mention next to a much
  // stronger signal does not stop a routine reply.
  const RUNNER_UP_FLOOR = 3; // one whole phrase, or three separate words
  if (secondScore >= RUNNER_UP_FLOOR && secondScore >= bestScore * 0.25) {
    return { category: "unclear", reason: "mixed_signals", scores, hits: [] };
  }

  return { category: bestName, reason: "clear", scores, hits: hits[bestName] };
}

/**
 * Pulls an order number out of the text.
 *
 * Shopify order names normally look like #1001, and stores often add a
 * prefix or suffix. Anything found is returned with the # kept, because that
 * is the form Shopify's own search expects.
 */
function extractOrderNumber(text) {
  const source = String(text || "");
  const patterns = [
    /#\s?([A-Z]{0,6}\d{3,10}[A-Z]{0,3})\b/i,
    /\border\s*(?:number|no\.?|#|id)?\s*[:\-]?\s*([A-Z]{0,6}\d{3,10}[A-Z]{0,3})\b/i,
    /\b(?:order|confirmation)\s+([A-Z]{1,6}[-_]?\d{3,10})\b/i,
  ];
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match && match[1]) {
      return `#${match[1].toUpperCase().replace(/^#/, "")}`;
    }
  }
  return null;
}

/*
 * Who actually sent this email?
 *
 * A From header has two halves. The mailbox in angle brackets is the one the
 * sender's mail provider vouches for. The display name in front of it is free
 * text the sender types into their own mail program, and it can contain an
 * address of its own:
 *
 *   From: "Jane <jane@example.com>" <stranger@evil.net>
 *
 * Nothing there is forged. The attacker's mailbox really is theirs, so the
 * message passes SPF, DKIM and every spam check clean. Reading the first
 * address out of the whole line hands them Jane's name, Jane's address and
 * Jane's parcel.
 *
 * So the rule is: one candidate address, or nobody. A From line that offers
 * two is refused, and the message goes to the owner unanswered. Refusing costs
 * a person ten seconds. Guessing costs a customer.
 */

/** Every address in a bracketed From line. Global: all of them, not the first. */
const BRACKETED_ADDRESS = /<([^<>@\s]+@[^<>@\s]+\.[a-z]{2,})>/gi;

/** An address written without brackets, in a display name or on its own. */
const ANY_ADDRESS = /[^\s<>@,;:"'()[\]]+@[^\s<>@,;:"'()[\]]+\.[a-z]{2,}/gi;

/** Lower-cased, de-duplicated, empties dropped. The same address twice is one. */
function distinctAddresses(values) {
  const found = [];
  for (const value of values) {
    const address = String(value == null ? "" : value)
      .trim()
      .toLowerCase();
    if (address.includes("@") && !found.includes(address)) found.push(address);
  }
  return found;
}

/**
 * The sender's address, read from a raw From header line.
 *
 * Returns null when the line names nobody, and null when it names more than
 * one — an ambiguous line is not something to pick a favourite from.
 */
function extractSenderEmail(from) {
  const source = String(from || "");
  const bracketed = distinctAddresses(
    [...source.matchAll(BRACKETED_ADDRESS)].map((match) => match[1]),
  );
  if (bracketed.length === 1) return bracketed[0];
  if (bracketed.length > 1) return null;
  const bare = distinctAddresses(
    [...source.matchAll(ANY_ADDRESS)].map((match) => match[0]),
  );
  return bare.length === 1 ? bare[0] : null;
}

/**
 * The sender's address, from whatever the mail node handed over.
 *
 * `from` is either the object a mail parser produces — { value: [{ address,
 * name }], text } — or a raw header line. The parsed address is preferred: it
 * is the mailbox, already separated from the display name, so a display name
 * cannot masquerade as it.
 *
 * Preferring it is not enough on its own. Parsers do not all split that header
 * the same way: one spelling of the trick above leaves the planted address in
 * `name`, another leaves it in `address` and the real sender in `name`. So
 * whichever side it lands on, the answer is the same — if the display name
 * names an address that is not the parsed one, nobody is identified.
 */
function senderAddress(from) {
  if (from && typeof from === "object" && !Array.isArray(from)) {
    const entries = Array.isArray(from.value) ? from.value : [];
    const addresses = distinctAddresses(entries.map((entry) => entry && entry.address));
    if (addresses.length > 1) return null; // two senders: refuse rather than pick
    if (addresses.length === 1) {
      const planted = distinctAddresses(
        entries.flatMap(
          (entry) => String((entry && entry.name) || "").match(ANY_ADDRESS) || [],
        ),
      ).filter((address) => address !== addresses[0]);
      return planted.length > 0 ? null : addresses[0];
    }
    return extractSenderEmail(from.text);
  }
  return extractSenderEmail(from);
}

/**
 * The whole read, in one call.
 *
 * Input:  { from, subject, body, headers }
 * Output: { handle, category, reason, orderNumber, customerEmail, cleanBody }
 */
function readEmail(email) {
  const cleanBody = stripQuotedHistory(email.body);
  // Read once, at the top. Every exit below reports the same answer, and there
  // is only one place the sender can be got wrong.
  const customerEmail = senderAddress(
    email && email.fromParsed ? email.fromParsed : email && email.from,
  );

  if (isAutomated(email)) {
    return {
      handle: false,
      category: "ignored",
      reason: "automated_mail",
      orderNumber: null,
      customerEmail,
      cleanBody,
    };
  }

  if (cleanBody.replace(/\s+/g, "").length < 10) {
    return {
      handle: false,
      category: "unclear",
      reason: "empty_message",
      orderNumber: null,
      customerEmail,
      cleanBody,
    };
  }

  // The subject line is part of the question, but only this message's subject.
  const searchText = `${email.subject || ""}\n${cleanBody}`;
  const verdict = categorise(searchText);

  return {
    handle: verdict.category !== "unclear",
    category: verdict.category,
    reason: verdict.reason,
    orderNumber: extractOrderNumber(searchText),
    customerEmail,
    cleanBody,
  };
}

/*
 * Talking to Shopify.
 *
 * One GraphQL query against the Admin API, asked either by order name or by
 * customer email. Read-only: the scopes this bot asks for are read_orders and
 * read_customers, and nothing here writes anything back.
 */

/**
 * Escapes a value going into Shopify's search syntax.
 *
 * Shopify's query strings are quoted, so an unescaped quote or backslash in a
 * customer's own text would change the meaning of the search. This is the
 * same class of problem as SQL injection, on a smaller stage.
 */
function escapeSearchValue(value) {
  return String(value == null ? "" : value)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"');
}

const ORDER_FIELDS = `
  id
  name
  createdAt
  displayFinancialStatus
  displayFulfillmentStatus
  cancelledAt
  email
  customer { firstName lastName email }
  shippingAddress {
    name address1 address2 city province zip country
  }
  lineItems(first: 20) {
    edges { node { title quantity } }
  }
  fulfillments(first: 10) {
    status
    trackingInfo { number url company }
  }
`;

const ORDER_QUERY = `query FindOrders($search: String!) {
  orders(first: 5, query: $search, sortKey: CREATED_AT, reverse: true) {
    edges { node {${ORDER_FIELDS}} }
  }
}`;

/**
 * Builds the search.
 *
 * By order number when we have one, because that is exact. By email address
 * otherwise, taking the most recent order, because that is what someone
 * asking "where is my order" almost always means.
 */
function buildOrderSearch({ orderNumber, customerEmail }) {
  if (orderNumber) {
    return {
      found: true,
      by: "order_number",
      search: `name:"${escapeSearchValue(orderNumber)}"`,
    };
  }
  if (customerEmail) {
    return {
      found: true,
      by: "customer_email",
      search: `email:"${escapeSearchValue(customerEmail)}"`,
    };
  }
  return { found: false, by: null, search: null };
}

/** The request body to POST at the Admin GraphQL endpoint. */
function buildRequestBody(searchString) {
  return { query: ORDER_QUERY, variables: { search: searchString } };
}

/** The Admin API address for a store, at a pinned API version. */
function adminApiUrl(storeDomain, apiVersion) {
  const domain = String(storeDomain || "")
    .trim()
    .replace(/^https?:\/\//i, "")
    .replace(/\/+$/, "");
  const version = String(apiVersion || "").trim() || "2024-10";
  return `https://${domain}/admin/api/${version}/graphql.json`;
}

/** Flattens one order into the handful of facts a reply actually needs. */
function summariseOrder(order) {
  const fulfillments = Array.isArray(order.fulfillments) ? order.fulfillments : [];
  const tracking = [];
  for (const fulfillment of fulfillments) {
    for (const info of fulfillment.trackingInfo || []) {
      if (info && info.number) {
        tracking.push({
          number: String(info.number),
          url: info.url ? String(info.url) : null,
          company: info.company ? String(info.company) : null,
        });
      }
    }
  }

  const address = order.shippingAddress || null;
  const items = ((order.lineItems || {}).edges || []).map((edge) => ({
    title: edge.node.title,
    quantity: edge.node.quantity,
  }));

  const customer = order.customer || {};
  const customerName = [customer.firstName, customer.lastName]
    .filter(Boolean)
    .join(" ")
    .trim();

  return {
    id: order.id,
    orderNumber: order.name,
    placedAt: order.createdAt,
    financialStatus: order.displayFinancialStatus || null,
    fulfillmentStatus: order.displayFulfillmentStatus || null,
    cancelled: Boolean(order.cancelledAt),
    cancelledAt: order.cancelledAt || null,
    email: order.email || customer.email || null,
    customerName: customerName || null,
    items,
    tracking,
    shippingAddress: address
      ? {
          name: address.name || null,
          line1: address.address1 || null,
          line2: address.address2 || null,
          city: address.city || null,
          province: address.province || null,
          zip: address.zip || null,
          country: address.country || null,
        }
      : null,
  };
}

/**
 * Reads Shopify's answer, including the ways it says no.
 *
 * GraphQL answers with HTTP 200 and an "errors" list, so a naive check on the
 * status code would treat a permissions failure as a successful empty search.
 * That would tell a customer their order does not exist when the real problem
 * is a missing scope.
 */
function parseOrderResponse(response) {
  if (!response || typeof response !== "object") {
    return { ok: false, problem: "no_response", orders: [] };
  }

  // Shopify answers a bad token with a plain string in "errors", and a bad
  // query with a list of objects. Both are failures and both must be read.
  const hasErrors =
    (Array.isArray(response.errors) && response.errors.length > 0) ||
    (typeof response.errors === "string" && response.errors.trim() !== "");

  if (hasErrors) {
    const messages = Array.isArray(response.errors)
      ? response.errors
          .map((error) => (error && error.message ? String(error.message) : "unknown error"))
          .join("; ")
      : String(response.errors);
    const permissionProblem = /access denied|not approved|required access scope|unauthorized/i.test(
      messages,
    );
    return {
      ok: false,
      problem: permissionProblem ? "permission_denied" : "api_error",
      message: messages,
      orders: [],
    };
  }

  const edges =
    response.data && response.data.orders && Array.isArray(response.data.orders.edges)
      ? response.data.orders.edges
      : null;

  if (!edges) {
    return { ok: false, problem: "unexpected_shape", orders: [] };
  }

  const orders = edges
    .filter((edge) => edge && edge.node)
    .map((edge) => summariseOrder(edge.node));

  if (orders.length === 0) {
    return { ok: true, problem: "not_found", orders: [] };
  }

  return { ok: true, problem: null, orders };
}

/**
 * Picks the order to reply about.
 *
 * Searching by order number should give exactly one. Searching by email can
 * give several, and the newest is the one being asked about. If an email
 * search turns up several recent orders, say so, because a reply about the
 * wrong one is worse than a question.
 */
function chooseOrder(parsed, searchedBy) {
  if (!parsed.ok || parsed.orders.length === 0) {
    return { order: null, ambiguous: false };
  }
  if (searchedBy === "order_number") {
    return { order: parsed.orders[0], ambiguous: parsed.orders.length > 1 };
  }
  const openOrders = parsed.orders.filter((order) => !order.cancelled);
  const pool = openOrders.length > 0 ? openOrders : parsed.orders;
  // Two orders in the last week, by email, with no order number given: a
  // person should decide which one they meant.
  const recent = pool.filter((order) => {
    const placed = Date.parse(order.placedAt);
    if (Number.isNaN(placed)) return false;
    return Date.now() - placed < 7 * 24 * 60 * 60 * 1000;
  });
  return { order: pool[0], ambiguous: recent.length > 1 };
}

// ---- n8n wiring. The tested logic is above this line. ----
// Input: the Gmail trigger's raw output, with your settings merged onto it.
// Output: one item per email, carrying the settings, the email, and the read.

const out = [];
for (const item of $input.all()) {
  const j = item.json;

  const settings = {
    storeDomain: j.storeDomain,
    apiVersion: j.apiVersion,
    storeName: j.storeName,
    signOffName: j.signOffName,
    ownerEmail: j.ownerEmail,
    autoSend: j.autoSend === true || j.autoSend === 'true',
    model: j.model,
    returnPolicy: j.returnPolicy,
  };

  // The Gmail trigger with Simplify switched off returns a parsed message:
  // "text" is the plain-text body, "from" is an object with a rendered "text"
  // field and a "value" array of addresses the parser has already separated
  // out, and "headers" is a map of header name to the whole header line.
  //
  // Two different things are wanted out of "from", so both are carried.
  // The rendered line is what the automated-mail check reads, because
  // "noreply" often appears only in the display name. The address the customer
  // is identified by comes from the parsed value instead, because a display
  // name is free text the sender types and can carry an address of its own.
  const fromParsed = j.from && typeof j.from === 'object' ? j.from : null;
  const fromLine =
    (fromParsed && (fromParsed.text || fromParsed.value?.[0]?.address)) ||
    (typeof j.from === 'string' ? j.from : '') ||
    j.From ||
    j.headers?.from ||
    '';

  const email = {
    from: String(fromLine),
    fromParsed,
    subject: String(j.subject || j.Subject || ''),
    body: String(j.text || j.textPlain || j.html || j.snippet || ''),
    headers: j.headers || {},
  };

  const read = readEmail(email);

  // Work out the Shopify search here too, so the next step can ask one
  // question: is there something to handle and something to look it up by?
  const search = buildOrderSearch({
    orderNumber: read.orderNumber,
    customerEmail: read.customerEmail,
  });

  out.push({
    json: {
      messageId: j.id || j.messageId || null,
      threadId: j.threadId || null,
      settings,
      email,
      read,
      shopify: {
        canSearch: search.found,
        searchedBy: search.by,
        url: search.found ? adminApiUrl(settings.storeDomain, settings.apiVersion) : null,
        body: search.found ? buildRequestBody(search.search) : null,
      },
    },
  });
}

return out;

/*
 * Kitset — Shopify support drafter.
 *
 * Everything down to the adapter at the bottom is copied straight from
 * the project's shopify.js and decide.js and pairing.js and is covered by its tests.
 * Editing it here means the tests no longer describe what runs.
 */

/*
 * Talking to Shopify.
 *
 * One GraphQL query against the Admin API, asked either by order name or by
 * customer email. Read-only: the scopes this bot asks for are read_orders and
 * read_customers, and nothing here writes anything back.
 */

/**
 * Escapes a value going into Shopify's search syntax.
 *
 * Shopify's query strings are quoted, so an unescaped quote or backslash in a
 * customer's own text would change the meaning of the search. This is the
 * same class of problem as SQL injection, on a smaller stage.
 */
function escapeSearchValue(value) {
  return String(value == null ? "" : value)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"');
}

const ORDER_FIELDS = `
  id
  name
  createdAt
  displayFinancialStatus
  displayFulfillmentStatus
  cancelledAt
  email
  customer { firstName lastName email }
  shippingAddress {
    name address1 address2 city province zip country
  }
  lineItems(first: 20) {
    edges { node { title quantity } }
  }
  fulfillments(first: 10) {
    status
    trackingInfo { number url company }
  }
`;

const ORDER_QUERY = `query FindOrders($search: String!) {
  orders(first: 5, query: $search, sortKey: CREATED_AT, reverse: true) {
    edges { node {${ORDER_FIELDS}} }
  }
}`;

/**
 * Builds the search.
 *
 * By order number when we have one, because that is exact. By email address
 * otherwise, taking the most recent order, because that is what someone
 * asking "where is my order" almost always means.
 */
function buildOrderSearch({ orderNumber, customerEmail }) {
  if (orderNumber) {
    return {
      found: true,
      by: "order_number",
      search: `name:"${escapeSearchValue(orderNumber)}"`,
    };
  }
  if (customerEmail) {
    return {
      found: true,
