/**
 * The whole decision, including what to do when there is nothing to reply
 * about.
 *
 * Returns an action, always one of:
 *   ignore  - machine mail, nothing happens
 *   draft   - write a reply and leave it for the owner
 *   send    - write a reply and send it
 *   escalate- do not write a reply, tell the owner what went wrong
 */
function decide({ settings, read, chosen, parsed }) {
  if (!read.handle && read.category === "ignored") {
    return { action: "ignore", why: "The message was not written by a person." };
  }

  if (!read.handle) {
    return {
      action: "escalate",
      why:
        read.reason === "mixed_signals"
          ? "The message asks about more than one thing at once."
          : "The message is not a clear order-status, return, or address question.",
    };
  }

  if (parsed && parsed.problem === "permission_denied") {
    return {
      action: "escalate",
      why:
        "Shopify refused the request. The access token is probably missing " +
        "the read_orders or read_customers scope.",
    };
  }
  if (parsed && (parsed.problem === "api_error" || parsed.problem === "unexpected_shape")) {
    return {
      action: "escalate",
      why: `Shopify did not answer as expected (${parsed.problem}). No reply was written.`,
    };
  }
  if (!chosen.order) {
    return {
      action: "escalate",
      why:
        "No matching order was found in Shopify, so anything written would " +
        "be a guess.",
    };
  }

  // Nothing about the order is written down, quoted, or handed to the model
  // until the person asking has been shown to be the person it belongs to.
  const owner = ownsOrder({ read, order: chosen.order });
  if (!owner.confirmed) {
    return {
      action: "escalate",
      why: NOT_THE_CUSTOMER[owner.reason],
      requesterConfirmed: false,
      requesterIsNotTheCustomer: true,
    };
  }

  const verdict = mayAutoSend({ settings, read, chosen, parsed });
  if (verdict.allowed) {
    return {
      action: "send",
      why: "Routine order-status question on a shipped order.",
      requesterConfirmed: true,
    };
  }

  return {
    action: "draft",
    why: `Left for you to check because ${verdict.reasons[0]}.`,
    allReasons: verdict.reasons,
    requesterConfirmed: true,
  };
}

/*
 * Lining answers up with the emails they belong to.
 *
 * n8n's HTTP nodes replace each item with the response they got, so the email
 * that produced a response is found by its position in an earlier node's
 * output. That only holds while the two lists are the same length. If they are
 * ever not, position means nothing, and pairing by position anyway would put
 * one customer's order into another customer's reply with no error anywhere.
 *
 * So the run stops instead. A stopped run shows up in n8n's execution list and
 * costs the owner a look. A quietly mispaired reply costs the customer.
 */
function pairByPosition(contexts, responses, whatAnswered) {
  const sent = Array.isArray(contexts) ? contexts.length : 0;
  const back = Array.isArray(responses) ? responses.length : 0;
  if (sent === back) return { ok: true, message: null };

  return {
    ok: false,
    message:
      `Kitset stopped on purpose. ${whatAnswered} returned ${back} answers ` +
      `for ${sent} emails, so there is no safe way to tell which answer ` +
      `belongs to which email. Nothing was sent and nothing was drafted. ` +
      `Open this run under Executions to see the emails involved and answer ` +
      `them yourself.`,
  };
}

// ---- n8n wiring. The tested logic is above this line. ----
// Reads Shopify's answer and decides what happens next.
//
// The HTTP node replaces the item with the response, so the context is taken
// from the true branch of "Do we handle it?", which lines up one for one with
// what was sent.

const context = $('Do we handle it?').all(0);
const responses = $input.all();

const paired = pairByPosition(context, responses, 'Ask Shopify');
if (!paired.ok) throw new Error(paired.message);

const out = [];

for (let i = 0; i < responses.length; i++) {
  const j = context[i].json;
  const raw = responses[i].json;

  // With "Never Error" switched on, an HTTP failure arrives here as data
  // rather than stopping the run. That is on purpose: the owner gets told
  // what went wrong instead of the workflow dying quietly.
  const parsed = parseOrderResponse(raw);
  const picked = chooseOrder(parsed, j.shopify.searchedBy);
  const chosen = { ...picked, searchedBy: j.shopify.searchedBy };

  const decision = decide({
    settings: j.settings,
    read: j.read,
    chosen,
    parsed,
